CREATE TABLE GameEdition(GameEditionID INTEGER PRIMARY KEY, GameID INTEGER NOT NULL, PlatformID INTEGER NOT NULL, ReleaseDate DATE, FileSizeGB DECIMAL(10,2), FOREIGN KEY (GameID) REFERENCES Game(GameID), FOREIGN KEY (PlatformID) REFERENCES Platform(PlatformID), UNIQUE(GameID, PlatformID), CHECK((FileSizeGB >= 0)));
